:root {
  --bg: #0f1115;
  --bg-alt: #171a21;
  --text: #f2f3f5;
  --muted: #9aa0ab;
  --accent: #4c8bf5;
  --border: #262a33;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
}

a {
  color: var(--accent);
  text-decoration: none;
}

.container {
  max-width: 960px;
  margin: 0 auto;
  padding: 0 24px;
}

.site-header {
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  background: var(--bg);
  z-index: 10;
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
}

.brand {
  font-weight: 700;
  font-size: 1.1rem;
}

.nav nav a {
  margin-left: 24px;
  color: var(--text);
}

.nav nav a:hover {
  color: var(--accent);
}

.hero {
  padding: 96px 24px;
  text-align: center;
}

.hero h1 {
  font-size: 2.75rem;
  margin: 0 0 12px;
}

.hero p {
  color: var(--muted);
  font-size: 1.1rem;
  margin: 0 0 28px;
}

.cta {
  display: inline-block;
  background: var(--accent);
  color: #fff;
  padding: 12px 28px;
  border-radius: 8px;
  font-weight: 600;
}

.section {
  padding: 64px 24px;
  border-top: 1px solid var(--border);
}

.section.alt {
  background: var(--bg-alt);
}

.section h2 {
  font-size: 1.75rem;
  margin-bottom: 16px;
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 20px;
  margin-top: 24px;
}

.card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 20px;
}

.card h3 {
  margin: 0 0 8px;
}

.card p {
  margin: 0;
  color: var(--muted);
}

.site-footer {
  border-top: 1px solid var(--border);
  padding: 24px;
  text-align: center;
  color: var(--muted);
  font-size: 0.9rem;
}
